<?php
function opsDateTime($value){$v=str_replace('T',' ',opsText($value,19));if(strlen($v)===16)$v.=':00';$d=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$v,new DateTimeZone('Asia/Qyzylorda'));if(!$d||$d->format('Y-m-d H:i:s')!==$v)throw new RuntimeException('Некорректные дата или время');return $d;}
function opsTime($v){if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/D',(string)$v))throw new RuntimeException('Время должно быть в формате ЧЧ:ММ');return $v;}
function opsSaveResource($pdo,$uid,$id,$d){$name=opsText($d['name']??'');if(!$name)throw new RuntimeException('Назовите мастера, стол или кабинет');$hours=[];foreach($d['hours']??[] as $day=>$h){$day=(int)$day;if($day<1||$day>7||empty($h['enabled']))continue;$start=opsTime($h['start']??'');$end=opsTime($h['end']??'');if($start>=$end)throw new RuntimeException('Окончание рабочего дня должно быть позже начала');$bs=$h['break_start']??'';$be=$h['break_end']??'';if($bs||$be){opsTime($bs);opsTime($be);if($bs<$start||$be>$end||$bs>=$be)throw new RuntimeException('Перерыв должен находиться внутри рабочего дня');}$hours[$day]=['start'=>$start,'end'=>$end,'break_start'=>$bs,'break_end'=>$be];}if(!$hours)throw new RuntimeException('Укажите хотя бы один рабочий день');$services=array_values(array_unique(array_map('intval',$d['service_ids']??[])));foreach($services as $itemId)if((opsItem($pdo,$uid,$itemId)['details']['kind']??'product')!=='service')throw new RuntimeException('Выбирайте позиции типа «Услуга»');$data=['hours'=>$hours,'service_ids'=>$services,'note'=>opsText($d['note']??'',500)];return opsTx($pdo,$uid,function()use($pdo,$uid,$id,$name,$data){if($id){$r=opsOne($pdo,'SELECT id FROM ops_resources WHERE user_id=? AND id=?',[$uid,$id]);if(!$r)throw new RuntimeException('Ресурс не найден');opsExec($pdo,'UPDATE ops_resources SET name=?,payload=? WHERE user_id=? AND id=?',[$name,opsJson($data),$uid,$id]);}else{opsExec($pdo,'INSERT INTO ops_resources(user_id,name,payload) VALUES(?,?,?)',[$uid,$name,opsJson($data)]);$id=(int)$pdo->lastInsertId();}opsAudit($pdo,$uid,'schedule_save',$id,['name'=>$name]);return ['id'=>$id];});}
function opsCheckSlot($pdo,$uid,$resourceId,$itemId,$start,$exclude=0){
    $resource=opsOne($pdo,'SELECT * FROM ops_resources WHERE user_id=? AND id=? AND active=1',[$uid,$resourceId]);if(!$resource)throw new RuntimeException('Мастер или ресурс недоступен');$config=json_decode($resource['payload'],true);$item=opsItem($pdo,$uid,$itemId);if(($item['details']['kind']??'product')!=='service')throw new RuntimeException('Для записи выберите услугу');if(!in_array($itemId,$config['service_ids']??[],true))throw new RuntimeException('Этот ресурс не оказывает выбранную услугу');$dt=opsDateTime($start);if($dt<new DateTimeImmutable('now',new DateTimeZone('Asia/Qyzylorda')))throw new RuntimeException('Выберите будущее время');if($dt>(new DateTimeImmutable('now',new DateTimeZone('Asia/Qyzylorda')))->modify('+365 days'))throw new RuntimeException('Запись доступна на год вперёд');$duration=(int)($item['details']['duration_minutes']??30);$end=$dt->modify('+'.$duration.' minutes');$hours=$config['hours'][(int)$dt->format('N')]??null;$date=$dt->format('Y-m-d');
    if(!$hours||$end->format('Y-m-d')!==$date||$dt->format('H:i')<$hours['start']||$end->format('H:i')>$hours['end'])throw new RuntimeException('Услуга не помещается в рабочее время');if(!empty($hours['break_start'])&&$dt->format('H:i')<$hours['break_end']&&$end->format('H:i')>$hours['break_start'])throw new RuntimeException('Это время пересекается с перерывом');
    $a=$dt->format('Y-m-d H:i:s');$b=$end->format('Y-m-d H:i:s');$overlap=opsOne($pdo,"SELECT id FROM ops_appointments WHERE user_id=? AND resource_id=? AND id<>? AND status IN ('requested','confirmed') AND starts_at<? AND ends_at>? LIMIT 1",[$uid,$resourceId,$exclude,$b,$a]);if($overlap)throw new RuntimeException('Время уже занято. Выберите другое окно.');
    // Preserve old fixed-slot bookings until the owner transfers them to the duration calendar.
    $legacy=opsOne($pdo,"SELECT id FROM aulieata_bookings WHERE user_id=? AND resource=? AND status='confirmed' AND starts_at<? AND DATE_ADD(starts_at,INTERVAL 60 MINUTE)>? LIMIT 1",[$uid,$resource['name'],$b,$a]);if($legacy)throw new RuntimeException('Пересечение с прежней записью (учтено 60 минут)');return ['resource'=>$resource['name'],'item'=>$item['item_name'],'starts_at'=>$a,'ends_at'=>$b,'duration'=>$duration];
}
function opsSlots($pdo,$uid,$resourceId,$itemId,$date){if(!validBusinessDate($date))throw new RuntimeException('Выберите дату');$out=[];for($minute=0;$minute<1440;$minute+=15){$at=$date.' '.sprintf('%02d:%02d:00',intdiv($minute,60),$minute%60);try{$slot=opsCheckSlot($pdo,$uid,$resourceId,$itemId,$at);$out[]=$slot;}catch(RuntimeException $e){}}return array_slice($out,0,96);}
function opsAppointmentSave($pdo,$uid,$d,$source='web',$chat=null){return opsTx($pdo,$uid,function()use($pdo,$uid,$d,$source,$chat){$id=(int)($d['id']??0);if(!$id&&!empty($d['request_key'])){$existing=opsOne($pdo,'SELECT id FROM ops_orders WHERE user_id=? AND request_key=?',[$uid,opsText($d['request_key'],80)]);if($existing){foreach(opsAll($pdo,'SELECT id,starts_at,ends_at,payload,status FROM ops_appointments WHERE user_id=?',[$uid]) as $a)if((int)(json_decode($a['payload'],true)['order_id']??0)===(int)$existing['id'])return ['id'=>$a['id'],'status'=>$a['status'],'starts_at'=>$a['starts_at'],'ends_at'=>$a['ends_at'],'duplicate'=>true];}}$resource=(int)($d['resource_id']??0);$item=(int)($d['item_id']??0);$slot=opsCheckSlot($pdo,$uid,$resource,$item,$d['starts_at']??'',$id);$old=null;if($id){$old=opsOne($pdo,'SELECT * FROM ops_appointments WHERE user_id=? AND id=? FOR UPDATE',[$uid,$id]);if(!$old||!in_array($old['status'],['requested','confirmed']))throw new RuntimeException('Запись нельзя перенести');if((int)$old['item_id']!==$item)throw new RuntimeException('Для смены услуги отмените запись и создайте новую');$body=json_decode($old['payload'],true);$chat=$old['chat_id'];$body['resource']=$slot['resource'];foreach(['client','phone','note'] as $field)if(isset($d[$field]))$body[$field]=opsText($d[$field],$field==='note'?1000:180);$body['reminder_optin']=!empty($d['reminder_optin']);opsExec($pdo,'UPDATE ops_appointments SET resource_id=?,starts_at=?,ends_at=?,payload=? WHERE user_id=? AND id=?',[$resource,$slot['starts_at'],$slot['ends_at'],opsJson($body),$uid,$id]);opsExec($pdo,"UPDATE ops_outbox SET status='cancelled' WHERE user_id=? AND ref_key LIKE ? AND status='queued'",[$uid,'appointment-'.$id.'-%']);if($chat)opsQueue($pdo,$uid,$chat,'appointment-'.$id.'-move-'.time(),'Запись №'.$id.' перенесена на '.$slot['starts_at'].' (UTC+5).');}
    else{$key=opsText($d['request_key']??'',80);$existing=opsOne($pdo,'SELECT id FROM ops_orders WHERE user_id=? AND request_key=?',[$uid,$key]);if($existing){foreach(opsAll($pdo,'SELECT id,payload,status FROM ops_appointments WHERE user_id=?',[$uid]) as $a)if((int)(json_decode($a['payload'],true)['order_id']??0)===(int)$existing['id'])return ['id'=>$a['id'],'status'=>$a['status'],'duplicate'=>true];}
        $order=opsCreateOrder($pdo,$uid,['items'=>[['item_id'=>$item,'quantity'=>1]],'quote_hash'=>$d['quote_hash']??'','request_key'=>$key,'client'=>$d['client']??'Гость','phone'=>$d['phone']??'','note'=>$d['note']??'','campaign_code'=>$d['campaign_code']??''],$source,$chat);$status=opsSettings($pdo,$uid)['auto_confirm_booking']?'confirmed':'requested';$body=['name'=>$slot['item'],'resource'=>$slot['resource'],'client'=>opsText($d['client']??'Гость'),'phone'=>opsText($d['phone']??'',50),'note'=>opsText($d['note']??'',1000),'order_id'=>$order['id'],'is_demo'=>$order['is_demo'],'reminder_optin'=>!empty($d['reminder_optin'])];opsExec($pdo,'INSERT INTO ops_appointments(user_id,resource_id,item_id,starts_at,ends_at,status,chat_id,payload,created_at) VALUES(?,?,?,?,?,?,?,?,?)',[$uid,$resource,$item,$slot['starts_at'],$slot['ends_at'],$status,$chat,opsJson($body),opsNow()]);$id=(int)$pdo->lastInsertId();if($status==='confirmed')opsOrderStatus($pdo,$uid,$order['id'],'accepted');}
    opsScheduleReminder($pdo,$uid,$id);opsAudit($pdo,$uid,$old?'appointment_move':'appointment_create',$id,['starts_at'=>$slot['starts_at'],'ends_at'=>$slot['ends_at']]);return ['id'=>$id,'status'=>$old['status']??$status,'starts_at'=>$slot['starts_at'],'ends_at'=>$slot['ends_at'],'resource'=>$slot['resource']];});}
function opsScheduleReminder($pdo,$uid,$id){$a=opsOne($pdo,'SELECT * FROM ops_appointments WHERE user_id=? AND id=?',[$uid,$id]);$d=json_decode($a['payload']??'{}',true);if(!$a||$a['status']!=='confirmed'||!$a['chat_id']||empty($d['reminder_optin']))return;$at=opsDateTime($a['starts_at'])->modify('-'.(int)opsSettings($pdo,$uid)['reminder_hours'].' hours')->format('Y-m-d H:i:s');opsQueue($pdo,$uid,$a['chat_id'],'appointment-'.$id.'-reminder-'.substr(hash('sha256',$a['starts_at']),0,12),'Напоминание: '.$d['name'].' · '.$a['starts_at'].' (UTC+5), '.$d['resource'].'. Для переноса или отмены напишите сотруднику.',max(opsNow(),$at));}
function opsAppointmentStatus($pdo,$uid,$id,$status){return opsTx($pdo,$uid,function()use($pdo,$uid,$id,$status){$a=opsOne($pdo,'SELECT * FROM ops_appointments WHERE user_id=? AND id=? FOR UPDATE',[$uid,$id]);if(!$a)throw new RuntimeException('Запись не найдена');if($a['status']===$status)return ['ok'=>true];$allow=['requested'=>['confirmed','cancelled'],'confirmed'=>['completed','cancelled']];if(!in_array($status,$allow[$a['status']]??[]))throw new RuntimeException('Нельзя изменить статус записи');$d=json_decode($a['payload'],true);if($status==='confirmed'){opsCheckSlot($pdo,$uid,(int)$a['resource_id'],(int)$a['item_id'],$a['starts_at'],$id);opsOrderStatus($pdo,$uid,$d['order_id'],'accepted');}if($status==='completed'&&$a['starts_at']>opsNow())throw new RuntimeException('Будущую запись нельзя отметить завершённой');if($status==='completed')opsOrderStatus($pdo,$uid,$d['order_id'],'completed');if($status==='cancelled'){opsOrderStatus($pdo,$uid,$d['order_id'],'cancelled');opsExec($pdo,"UPDATE ops_outbox SET status='cancelled' WHERE user_id=? AND ref_key LIKE ? AND status='queued'",[$uid,'appointment-'.$id.'-%']);}opsExec($pdo,'UPDATE ops_appointments SET status=? WHERE user_id=? AND id=?',[$status,$uid,$id]);if($status==='confirmed')opsScheduleReminder($pdo,$uid,$id);if($a['chat_id'])opsQueue($pdo,$uid,$a['chat_id'],'appointment-'.$id.'-'.$status,'Запись №'.$id.' '.(['confirmed'=>'подтверждена','completed'=>'завершена','cancelled'=>'отменена'][$status]).'. '.$a['starts_at'].' (UTC+5).');opsAudit($pdo,$uid,'appointment_status',$id,['before'=>$a['status'],'after'=>$status]);return ['ok'=>true];});}
function opsRunOutbox($pdo,$limit=20){$count=0;$rows=opsAll($pdo,"SELECT * FROM ops_outbox WHERE status='queued' AND due_at<=? ORDER BY id LIMIT ".(int)$limit,[opsNow()]);$cfg=require dirname(__DIR__).'/aulieata-secrets.php';foreach($rows as $r){if(!opsExec($pdo,"UPDATE ops_outbox SET status='sending' WHERE id=? AND status='queued'",[$r['id']]))continue;try{$c=opsOne($pdo,'SELECT token_box FROM aulieata_connections WHERE user_id=? AND active=1',[$r['user_id']]);if(!$c)throw new RuntimeException('Telegram не подключён');telegramCall(openToken($c['token_box'],$cfg),'sendMessage',['chat_id'=>$r['chat_id'],'text'=>$r['text']]);opsExec($pdo,"UPDATE ops_outbox SET status='sent' WHERE id=?",[$r['id']]);$count++;}catch(Throwable $e){opsExec($pdo,"UPDATE ops_outbox SET status='failed' WHERE id=?",[$r['id']]);}}return $count;}
